def tr(key, language='en', **values):
    """Translate framing; ``code`` remains available as a format argument."""
    row = ROWS.get(key, ROWS['unknown'])
    return row[CODES.index(language) if language in CODES else 1].format(**values)


def install_catalogue():
    """Only navigation belongs to the dialog-wide translation catalogue."""
    from jarvis.i18n import EXACT
    for key in ('title', 'subtitle'):
        EXACT[ROWS[key][0]] = dict(zip(CODES[1:], ROWS[key][1:]))
